css:
.filosim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #34291f;
    background: linear-gradient(165deg, #faf4ea 0%, #f3e7d6 55%, #efddc8 100%);
    border-radius: 18px;
}

.filosim-container * {
    box-sizing: border-box;
}

.filosim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #2b211a 0%, #4a352a 55%, #6b3f2e 100%);
    color: #fbf2e6;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #5a4232;
    box-shadow: 0 12px 34px rgba(43, 33, 26, 0.35);
}

.filosim-header h1 {
    margin: 10px 0 12px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: 0.4px;
    color: #fdf6ea;
    font-family: Georgia, 'Times New Roman', serif;
}

.filosim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.4px;
    font-weight: 700;
    color: #e8a87c;
    background: rgba(232, 168, 124, 0.14);
    border: 1px solid rgba(232, 168, 124, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.filosim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.6;
    color: #ecddca;
}

.filosim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #7a6452;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.filosim-period-counter #currentDay,
.filosim-period-counter #maxPeriods {
    font-weight: 800;
    color: #b85c38;
}

.filosim-round-name {
    background: rgba(184, 92, 56, 0.14);
    color: #b85c38;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.filosim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a5b2a;
    background: rgba(214, 152, 84, 0.16);
    border: 1px solid rgba(214, 152, 84, 0.40);
    padding: 4px 12px;
    border-radius: 999px;
}

.filosim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.filosim-status-card {
    background: #fffaf2;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e6d5bf;
    box-shadow: 0 6px 18px rgba(120, 90, 60, 0.10);
    border-top: 4px solid #c98b5e;
}

.filosim-card-scale { border-top-color: #3f7d6e; }
.filosim-card-brand { border-top-color: #b85c38; }
.filosim-card-intl { border-top-color: #7a6cae; }
.filosim-card-runway { border-top-color: #c7973f; }

.filosim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.7px;
    font-weight: 700;
    color: #9a8268;
}

.filosim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #34291f;
    font-variant-numeric: tabular-nums;
    font-family: Georgia, 'Times New Roman', serif;
}

.filosim-card-scale .filosim-value { color: #2f6f60; }
.filosim-card-brand .filosim-value { color: #b85c38; }
.filosim-card-intl .filosim-value { color: #6857a0; }
.filosim-card-runway .filosim-value { color: #b78327; }

.filosim-sublabel {
    font-size: 0.76rem;
    color: #8c7762;
    line-height: 1.35;
}

.filosim-runway-low { border-top-color: #c0392b; }
.filosim-runway-low .filosim-value { color: #c0392b; }
.filosim-runway-high { border-top-color: #3f7d6e; }
.filosim-runway-high .filosim-value { color: #2f6f60; }

.filosim-brand-low { border-top-color: #c0392b; }
.filosim-brand-low .filosim-value { color: #c0392b; }

.filosim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #fff6ea;
    border: 1px solid #e6d5bf;
    color: #5a4636;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.filosim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #b85c38;
}

.filosim-briefing {
    display: flex;
    gap: 14px;
    background: #fffaf2;
    border-left: 5px solid #b85c38;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(120, 90, 60, 0.10);
}

.filosim-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.filosim-briefing-title {
    font-weight: 800;
    font-size: 1.1rem;
    color: #34291f;
    margin-bottom: 6px;
    font-family: Georgia, 'Times New Roman', serif;
}

.filosim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.6;
    color: #534437;
}

.filosim-briefing-text strong { color: #b85c38; }
.filosim-briefing-text em { color: #2f6f60; font-style: italic; }

.filosim-controls {
    background: #fffaf2;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e6d5bf;
    box-shadow: 0 6px 18px rgba(120, 90, 60, 0.10);
}

.filosim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.14rem;
    font-weight: 800;
    color: #34291f;
    border-bottom: 2px solid #ecdcc6;
    padding-bottom: 8px;
    font-family: Georgia, 'Times New Roman', serif;
}

.filosim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #4a3b2d;
    margin: 14px 0 6px;
}

.filosim-container select,
.filosim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d8c4a9;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fffdf9;
    color: #34291f;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.filosim-container select:focus,
.filosim-container input[type="number"]:focus {
    outline: none;
    border-color: #b85c38;
    box-shadow: 0 0 0 3px rgba(184, 92, 56, 0.16);
}

.filosim-container select option {
    background-color: #fffdf9;
    color: #34291f;
}

.filosim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #b85c38;
}

.filosim-range-readout,
.filosim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #7a6452;
    margin-top: 4px;
}

.filosim-range-readout span:last-child,
.filosim-alloc-readout span:nth-child(2) {
    color: #b85c38;
    font-weight: 800;
}

.filosim-hint {
    font-size: 0.8rem;
    color: #8c7762;
    margin-top: 4px;
    line-height: 1.45;
}

.filosim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.filosim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #fdf6ea;
    border: 1px solid #e3d2ba;
    border-radius: 9px;
    padding: 8px 12px;
}

.filosim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #4a3b2d;
}

.filosim-alloc-row input[type="number"] {
    width: 96px;
    flex: 0 0 96px;
}

.filosim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.filosim-container .btn-primary {
    background: linear-gradient(135deg, #9a4326 0%, #c96f44 100%);
    border: none;
    color: #fff6ee;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 20px rgba(154, 67, 38, 0.32);
}

.filosim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.filosim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d8c4a9;
    color: #7a6452;
    background: transparent;
}

.filosim-coach {
    background: linear-gradient(160deg, #2b211a 0%, #3a2a3a 100%);
    color: #ecddca;
    border: 1px solid #4a3142;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(43, 33, 26, 0.30);
}

.filosim-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e8a87c;
    margin-bottom: 8px;
}

.filosim-coach-body {
    font-size: 0.95rem;
    line-height: 1.6;
}

.filosim-coach-body strong { color: #e8a87c; }
.filosim-coach-body em { color: #9bc7b9; font-style: italic; }

.filosim-history,
.filosim-chart {
    background: #fffaf2;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e6d5bf;
    box-shadow: 0 6px 18px rgba(120, 90, 60, 0.10);
}

.filosim-history h3,
.filosim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.1rem;
    font-weight: 800;
    color: #34291f;
    font-family: Georgia, 'Times New Roman', serif;
}

.filosim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #4a3b2d;
}

.filosim-container table#usfHistoryTable th {
    background: #fdf0df;
    color: #9a4326;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e3d2ba;
}

.filosim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #ecdcc6;
    color: #534437;
}

.filosim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #fdf6ea;
}

.filosim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .filosim-container {
        padding: 14px;
    }
    .filosim-header h1 {
        font-size: 1.8rem;
    }
    .filosim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .filosim-value {
        font-size: 2rem;
    }
    .filosim-clock {
        margin-left: 0;
    }
    .filosim-period-counter {
        font-size: 0.88rem;
    }
    .filosim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .filosim-alloc-row {
        flex-wrap: wrap;
    }
    .filosim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .filosim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ============================================================
   v1.1.0 — Completion debrief (append-only, scoped .filo-cm)
   Palette: terracotta #b85c38 · brown #34291f · red #c0392b
   ============================================================ */
.filo-cm { font-family: inherit; color: #34291f; text-align: left; }
.filo-cm-head { display: flex; align-items: center; gap: 20px; flex-wrap: wrap;
    border-bottom: 3px solid #b85c38; padding-bottom: 14px; margin-bottom: 16px; }
.filo-cm-scorebox { display: flex; flex-direction: column; align-items: center;
    background: #b85c38; color: #fff; border-radius: 12px; padding: 12px 20px; min-width: 130px; }
.filo-cm-score { font-size: 2.6rem; line-height: 1; font-weight: 800; }
.filo-cm-score-max { font-size: 1rem; font-weight: 600; opacity: 0.8; margin-left: 2px; }
.filo-cm-score-label { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.06em; opacity: 0.9; margin-top: 4px; }
.filo-cm-tier { font-size: 1.5rem; font-weight: 700; color: #34291f; flex: 1 1 auto; }
.filo-cm-chips { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 16px; }
.filo-cm-chip { flex: 1 1 160px; display: flex; align-items: center; gap: 8px;
    background: #fdf6ea; border: 1px solid #e6d5bf; border-left: 5px solid #7a6452; border-radius: 8px; padding: 9px 12px; }
.filo-cm-chip.is-met { border-left-color: #3f7d54; }
.filo-cm-chip.is-missed { border-left-color: #c0392b; }
.filo-cm-chip-l { font-weight: 600; color: #4a3d30; font-size: 0.9rem; }
.filo-cm-badge { margin-left: auto; font-size: 0.68rem; font-weight: 700; text-transform: uppercase;
    letter-spacing: 0.04em; padding: 3px 8px; border-radius: 999px; color: #fff; }
.filo-cm-badge.is-met { background: #3f7d54; }
.filo-cm-badge.is-missed { background: #c0392b; }
.filo-cm-kpis { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 18px; }
.filo-cm-kpi { flex: 1 1 110px; text-align: center; background: #fffaf2; border: 1px solid #e6d5bf;
    border-top: 3px solid #e8a87c; border-radius: 8px; padding: 10px 8px; }
.filo-cm-kpi-v { font-size: 1.3rem; font-weight: 800; color: #b85c38; font-variant-numeric: tabular-nums; }
.filo-cm-kpi-l { font-size: 0.7rem; text-transform: uppercase; letter-spacing: 0.04em; color: #7a6452; margin-top: 3px; }
.filo-cm-insights-title { font-weight: 700; color: #34291f; margin-bottom: 6px; }
.filo-cm-insights ul { margin: 0; padding-left: 20px; }
.filo-cm-insights li { margin-bottom: 7px; line-height: 1.5; }

