(function() {
    'use strict';

    class FiloAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Creative Pivot`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Filo Studio S.r.l.).
            this.REVENUE = 2.8;              // EUR 2.8M Year-3 revenue
            this.COMMUNITY = 140;           // 140k engaged followers
            this.KNOWLEDGE_BUDGET = 600;    // EUR 600k ring-fenced knowledge & capability budget (k)
            this.TRANCHE = 800;             // EUR 800k second tranche
            this.RUNWAY_START = 11;         // months at current burn
            this.RUNWAY_WITHHELD = 5;       // months if tranche withheld
            this.LOST_DEMAND = 320;         // ~EUR 320k of demand lost to capacity

            // Concept truths (the defensible, founder-independent, knowledge-driven path).
            this.TRUE_ASSET = `signature`;
            this.TRUE_CONSTRAINT = `all`;
            this.TRUE_MODEL = `capturemix`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    scale: 18,                 // defensible, founder-independent value capture (0–100)
                    brand: 62,                 // brand equity / community engagement (0–100)
                    intl: 10,                  // internationalization knowledge & network readiness (0–100)
                    runway: 11,                // months of cash runway
                    budgetUsed: 0,             // EUR k of knowledge budget committed
                    founderLocked: false,      // model still routed through the founders
                    brandDiluted: false,       // signature licensed broadly / sold out
                    budgetWasted: false,       // knowledge budget spent on marketing / inventory
                    trancheUnlocked: false,
                    scaleHistory: [18],
                    brandHistory: [62],
                    intlHistory: [10],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately WRONG-LEANING firefighting mix —
                // a blind click-through must NOT auto-win (defaults scale the copyable
                // product, keep founders in the loop, go owned-stores everywhere, and
                // split the budget evenly including the forbidden marketing bucket).
                state.decisions = {
                    asset: `product`,
                    constraint: `none`,
                    intent: 40,
                    model: `moredrops`,
                    mix: 30,
                    systematize: `founders`,
                    mode: `ownedstores`,
                    market: `threeplus`,
                    knowledge: 35,
                    hires: 120,
                    ipsystem: 120,
                    marketk: 120,
                    network: 120,
                    marketing: 120,
                    kpi: `revenueonly`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const as = document.getElementById(`assetInput`);
                const co = document.getElementById(`constraintInput`);
                const it = document.getElementById(`intentInput`);
                if (as) decisions.asset = as.value;
                if (co) decisions.constraint = co.value;
                if (it) decisions.intent = parseInt(it.value, 10);
                if (!Number.isFinite(decisions.intent) || decisions.intent < 0 || decisions.intent > 100) {
                    warn(`warn_intent_range`); return false;
                }
            } else if (round === 2) {
                const md = document.getElementById(`modelInput`);
                const mx = document.getElementById(`mixInput`);
                const sy = document.getElementById(`systematizeInput`);
                if (md) decisions.model = md.value;
                if (mx) decisions.mix = parseInt(mx.value, 10);
                if (sy) decisions.systematize = sy.value;
                if (!Number.isFinite(decisions.mix) || decisions.mix < 0 || decisions.mix > 100) {
                    warn(`warn_mix_range`); return false;
                }
            } else if (round === 3) {
                const mo = document.getElementById(`modeInput`);
                const mk = document.getElementById(`marketInput`);
                const kn = document.getElementById(`knowledgeInput`);
                if (mo) decisions.mode = mo.value;
                if (mk) decisions.market = mk.value;
                if (kn) decisions.knowledge = parseInt(kn.value, 10);
                if (!Number.isFinite(decisions.knowledge) || decisions.knowledge < 0 || decisions.knowledge > 100) {
                    warn(`warn_knowledge_range`); return false;
                }
            } else if (round === 4) {
                const h = document.getElementById(`hiresInput`);
                const i = document.getElementById(`ipsystemInput`);
                const m = document.getElementById(`marketkInput`);
                const n = document.getElementById(`networkInput`);
                const g = document.getElementById(`marketingInput`);
                const kp = document.getElementById(`kpiInput`);
                const cv = document.getElementById(`convictionInput`);
                if (h) decisions.hires = parseFloat(h.value);
                if (i) decisions.ipsystem = parseFloat(i.value);
                if (m) decisions.marketk = parseFloat(m.value);
                if (n) decisions.network = parseFloat(n.value);
                if (g) decisions.marketing = parseFloat(g.value);
                if (kp) decisions.kpi = kp.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                const parts = [decisions.hires, decisions.ipsystem, decisions.marketk, decisions.network, decisions.marketing];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round(decisions.hires + decisions.ipsystem + decisions.marketk + decisions.network + decisions.marketing);
                if (Math.abs(total - this.KNOWLEDGE_BUDGET) > 0.5) {
                    warn(`warn_alloc_total`); return false;
                }
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let scaleDelta = 0, brandDelta = 0, intlDelta = 0, runwayDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the defensible asset (Common Error 1: scaling the copyable product).
                switch (d.asset) {
                    case `signature`: scaleDelta += 12; brandDelta += 4; coachKey = `coach_r1_signature`; break;
                    case `product`: scaleDelta -= 6; brandDelta -= 4; coachKey = `coach_r1_product`; break;
                    case `price`: scaleDelta -= 8; brandDelta -= 6; coachKey = `coach_r1_price`; break;
                    case `celebrity`: scaleDelta -= 4; brandDelta -= 2; coachKey = `coach_r1_celebrity`; break;
                }

                // Name the model's three fatal constraints.
                switch (d.constraint) {
                    case `all`: scaleDelta += 10; intlDelta += 4; if (d.asset === `signature`) coachKey = `coach_r1_sharp`; break;
                    case `capacity`: scaleDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r1_capacity` : coachKey; break;
                    case `marketing`: scaleDelta -= 4; brandDelta -= 2; break;
                    case `none`: scaleDelta -= 6; coachKey = `coach_r1_none`; break;
                }

                if (d.intent >= 60) { scaleDelta += 6; }
                else if (d.intent <= 25) { scaleDelta -= 5; coachKey = `coach_r1_lowintent`; }

                summaryKey = (d.asset === `signature` && d.constraint === `all`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Reshape the model (Common Errors 1 & 2: scaling the copy / founder dependence).
                switch (d.model) {
                    case `capturemix`:
                        scaleDelta += 14; brandDelta += 4; runwayDelta += 1; coachKey = `coach_r2_capturemix`; break;
                    case `moredrops`:
                        // Scaling the copyable product into a price war it cannot win.
                        scaleDelta -= 8; brandDelta -= 4; runwayDelta -= 1; coachKey = `coach_r2_moredrops`; break;
                    case `licensebroad`:
                        // Fast royalties, but the signature commoditizes — brand equity spent.
                        scaleDelta += 6; brandDelta -= 14; ds.brandDiluted = true; coachKey = `coach_r2_licensebroad`; break;
                    case `serviceonly`:
                        // Trades the brand asset for project work — caps the upside, dents equity.
                        scaleDelta += 2; brandDelta -= 8; coachKey = `coach_r2_serviceonly`; break;
                }

                // Target recurring / non-drop mix breaks the capacity ceiling.
                if (d.mix >= 50) { scaleDelta += 8; }
                else if (d.mix >= 30) { scaleDelta += 3; }
                else { scaleDelta -= 4; if (coachKey === `coach_r2_capturemix`) coachKey = `coach_r2_lowmix`; }

                // Systematize the design signature (Common Error 2: founder dependence).
                switch (d.systematize) {
                    case `system`: scaleDelta += 10; brandDelta += 3; intlDelta += 4; break;
                    case `partial`: scaleDelta += 2; break;
                    case `founders`:
                        scaleDelta -= 8; ds.founderLocked = true;
                        coachKey = `coach_r2_founders`; break;
                }

                summaryKey = (d.model === `capturemix` && d.systematize === `system` && d.mix >= 40) ? `sum_r2_good` :
                             (d.model === `moredrops` ? `sum_r2_moredrops` :
                             (d.systematize === `founders` ? `sum_r2_founders` : `sum_r2_weak`));
            } else if (round === 3) {
                // Entry mode = knowledge & network problem (Common Error 3: over-aggressive mode).
                const k = d.knowledge / 100;
                switch (d.mode) {
                    case `digitalexport`:
                        // Leverages the existing community cheaply — social capital already owned.
                        intlDelta += 10 + k * 8; brandDelta += 2; runwayDelta += 0.5;
                        coachKey = `coach_r3_digital`; break;
                    case `jv`:
                        // Imports local knowledge & network at the cost of shared upside.
                        intlDelta += 8 + k * 10; scaleDelta += 2;
                        coachKey = `coach_r3_jv`; break;
                    case `wholesale`:
                        // Borrows foreign buyers' shelf — moderate, needs relationships.
                        intlDelta += 6 + k * 7; coachKey = `coach_r3_wholesale`; break;
                    case `ownedstores`:
                        // High control, high capital, with no local buyers or market knowledge.
                        intlDelta += 2 + k * 6; runwayDelta -= 2 - k * 1.2;
                        coachKey = (k < 0.4) ? `coach_r3_ownedstores` : `coach_r3_ownedfunded`; break;
                }

                // Priority-market concentration vs. spreading thin before the copy spreads.
                switch (d.market) {
                    case `onefocus`: intlDelta += 8; if (coachKey === `coach_default`) coachKey = `coach_r3_focus`; break;
                    case `threeplus`: intlDelta -= 6; runwayDelta -= 1; if (d.mode === `ownedstores`) coachKey = `coach_r3_blitz`; break;
                    case `random`: intlDelta -= 8; brandDelta -= 3; coachKey = `coach_r3_random`; break;
                }

                // Explicitly funding the required knowledge/network.
                if (d.knowledge >= 60) { intlDelta += 6; }
                else if (d.knowledge <= 25) { intlDelta -= 5; if (coachKey === `coach_default`) coachKey = `coach_r3_underfunded`; }

                summaryKey = ((d.mode === `digitalexport` || d.mode === `jv`) && d.market === `onefocus` && d.knowledge >= 40) ? `sum_r3_good` :
                             (d.mode === `ownedstores` && d.market === `threeplus` ? `sum_r3_blitz` : `sum_r3_weak`);
            } else if (round === 4) {
                // Allocate the EUR 600k knowledge budget (Common Error 4: marketing/inventory).
                const compound = d.hires + d.ipsystem + d.marketk + d.network;   // capability that compounds
                const wasted = d.marketing;                                       // consumable demand (forbidden intent)
                spend = compound + wasted;

                // Compounding buckets build durable capability across all three KPIs.
                scaleDelta += (d.hires / 100) * 6 + (d.ipsystem / 100) * 6;
                brandDelta += (d.ipsystem / 100) * 3 + (d.network / 100) * 2;
                intlDelta += (d.marketk / 100) * 6 + (d.network / 100) * 6;

                // The ring-fence was against exactly this: marketing/inventory buys a quarter
                // of sales, not capability — it erodes scalability and burns runway.
                if (wasted >= 200) {
                    ds.budgetWasted = true;
                    scaleDelta -= 8; runwayDelta -= 1; coachKey = `coach_r4_wasted`;
                } else if (wasted >= 100) {
                    scaleDelta -= 3; coachKey = `coach_r4_somewaste`;
                } else if (compound >= 550) {
                    coachKey = `coach_r4_compound`;
                }

                // The 18-month KPI scorecard (Common Error 5: revenue-only / vanity metrics).
                switch (d.kpi) {
                    case `balanced`: scaleDelta += 6; brandDelta += 6; intlDelta += 4; if (coachKey === `coach_default`) coachKey = `coach_r4_balanced`; break;
                    case `revenueonly`: brandDelta -= 8; coachKey = (coachKey === `coach_default`) ? `coach_r4_revenueonly` : coachKey; break;
                    case `vanity`: brandDelta -= 4; scaleDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r4_vanity` : coachKey; break;
                }

                if (d.conviction >= 60) { scaleDelta += 4; }
                else if (d.conviction <= 25) { scaleDelta -= 4; }

                summaryKey = (compound >= 550 && d.kpi === `balanced`) ? `sum_r4_good` :
                             (ds.budgetWasted ? `sum_r4_wasted` : `sum_r4_weak`);
            }

            // Knowledge-budget accounting (metered in R4; EUR k).
            ds.budgetUsed = Math.min(this.KNOWLEDGE_BUDGET, Math.round(ds.budgetUsed + spend));

            // Apply deltas; KPIs clamped 0–100, runway floored at 0.
            ds.scale = Math.max(0, Math.min(100, Math.round(ds.scale + scaleDelta)));
            ds.brand = Math.max(0, Math.min(100, Math.round(ds.brand + brandDelta)));
            ds.intl = Math.max(0, Math.min(100, Math.round(ds.intl + intlDelta)));
            ds.runway = Math.max(0, Math.round((ds.runway + runwayDelta) * 10) / 10);

            ds.scaleHistory.push(ds.scale);
            ds.brandHistory.push(ds.brand);
            ds.intlHistory.push(ds.intl);

            // Final round: the integrated pivot is judged — does the tranche unlock?
            if (round === 4) {
                const credible = ds.scale >= 55 && ds.intl >= 45 && ds.brand >= 50 && !ds.budgetWasted;
                if (credible) {
                    ds.trancheUnlocked = true;
                    ds.runway = Math.round((ds.runway + 6) * 10) / 10;   // EUR 800k tranche extends runway
                } else {
                    ds.trancheUnlocked = false;
                    ds.runway = Math.min(ds.runway, this.RUNWAY_WITHHELD); // withheld → down to ~5 months
                }
            }

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0: persist the composite where results_utils.php reads it (per-period + final).
            const _score = this._composite(ds);
            ds.score = _score;
            if (!ds.performance || typeof ds.performance !== `object`) { ds.performance = {}; }
            ds.performance.overallScore = _score;

            return {
                period: state.currentPeriod,
                score: _score,
                scale: ds.scale,
                scaleDelta: Math.round(scaleDelta),
                brand: ds.brand,
                brandDelta: Math.round(brandDelta),
                intl: ds.intl,
                intlDelta: Math.round(intlDelta),
                runway: ds.runway,
                budgetUsed: ds.budgetUsed,
                founderLocked: ds.founderLocked,
                brandDiluted: ds.brandDiluted,
                budgetWasted: ds.budgetWasted,
                trancheUnlocked: ds.trancheUnlocked,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
            // Locale-aware EUR in thousands: English "€600k", Spanish "600k€".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.round(Math.abs(v));
            if (lang === `es`) {
                return `${sign}${abs}k€`;
            }
            return `${sign}€${abs}k`;
        }

        _fmtRunway(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const n = Math.round(Number(v) * 10) / 10;
            const unit = (lang === `es`) ? `mes` : `mo`;
            return `${n} ${unit}`;
        }

