            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`scaleDisplay`, `domainState.scale`, (v) => Math.round(Number(v)));
