                const card = document.querySelector(`.filosim-card-brand`);
                if (card) card.classList.toggle(`filosim-brand-low`, Number(v) <= 40);
                return Math.round(Number(v));
            });
            uiManager.bind(`intlDisplay`, `domainState.intl`, (v) => Math.round(Number(v)));
