                const card = document.querySelector(`.filosim-card-runway`);
                if (card) {
                    card.classList.toggle(`filosim-runway-low`, Number(v) <= 6);
                    card.classList.toggle(`filosim-runway-high`, Number(v) >= 14);
                }
                return self._fmtRunway(Number(v));
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                return self._fmtMoney(Number(v)) + ` / ` + self._fmtMoney(self.KNOWLEDGE_BUDGET);
