            // Intent slider readout.
            const it = document.getElementById(`intentInput`);
            const itReadout = document.getElementById(`intentReadout`);
            if (it && itReadout) {
                itReadout.textContent = it.value;
                it.addEventListener(`input`, function() { itReadout.textContent = it.value; });
            }

            // Mix slider readout.
            const mx = document.getElementById(`mixInput`);
            const mxReadout = document.getElementById(`mixReadout`);
            if (mx && mxReadout) {
                mxReadout.textContent = mx.value;
                mx.addEventListener(`input`, function() { mxReadout.textContent = mx.value; });
            }

            // Knowledge slider readout.
            const kn = document.getElementById(`knowledgeInput`);
            const knReadout = document.getElementById(`knowledgeReadout`);
            if (kn && knReadout) {
                knReadout.textContent = kn.value;
                kn.addEventListener(`input`, function() { knReadout.textContent = kn.value; });
            }

            // Knowledge-budget live total (must hit EUR 600k).
            const allocIds = [`hiresInput`, `ipsystemInput`, `marketkInput`, `networkInput`, `marketingInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (allocReadout) allocReadout.textContent = total;
                const bar = document.querySelector(`.filosim-alloc-readout`);
                if (bar) bar.style.color = (Math.abs(total - self.KNOWLEDGE_BUDGET) > 0.5) ? `#c0392b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

