        _composite(ds) {
            // v1.1.0: verbatim v1.0.0 formula, extracted so calculateResults can persist it every period.
            const scale = Math.round(ds.scale);
            const brand = Math.round(ds.brand);
            const intl = Math.round(ds.intl);
            const trancheScore = ds.trancheUnlocked ? 12 : 0;
            return Math.round(scale * 0.34 + brand * 0.28 + intl * 0.26 + trancheScore);
        }

        formatCompletionMessage(summary) {
            // v1.1.0: localized debrief; without this override the engine discards score/tier/insights.
            const t = (k) => (window.mySimulation ? window.mySimulation.t(k) : k);
            if (!summary || typeof summary.composite === `undefined`) {
                return `<div class="filo-cm"><div class="filo-cm-tier">${t(`grade_stalled`)}</div></div>`;
            }
            const tier = summary.performance || t(summary.performanceKey || `grade_stalled`);
            const chip = (ok, label) => `<div class="filo-cm-chip ${ok ? `is-met` : `is-missed`}"><span class="filo-cm-chip-l">${label}</span><span class="filo-cm-badge ${ok ? `is-met` : `is-missed`}">${ok ? t(`cm_met`) : t(`cm_missed`)}</span></div>`;
            const lis = (summary.insights || []).map((s) => `<li>${s}</li>`).join(``);
            return `
                <div class="filo-cm">
                    <div class="filo-cm-head">
                        <div class="filo-cm-scorebox">
                            <div class="filo-cm-score">${summary.composite}<span class="filo-cm-score-max">/100</span></div>
                            <div class="filo-cm-score-label">${t(`cm_score_label`)}</div>
                        </div>
                        <div class="filo-cm-tier">${tier}</div>
                    </div>
                    <div class="filo-cm-chips">
                        ${chip(summary.scalable, t(`cm_chip_scalable`))}
                        ${chip(summary.defensible, t(`cm_chip_defensible`))}
                        ${chip(summary.intlReady, t(`cm_chip_intl`))}
                        ${chip(summary.trancheUnlocked, t(`cm_chip_tranche`))}
                    </div>
                    <div class="filo-cm-kpis">
                        <div class="filo-cm-kpi"><div class="filo-cm-kpi-v">${summary.scale}</div><div class="filo-cm-kpi-l">${t(`cm_kpi_scale`)}</div></div>
                        <div class="filo-cm-kpi"><div class="filo-cm-kpi-v">${summary.brand}</div><div class="filo-cm-kpi-l">${t(`cm_kpi_brand`)}</div></div>
                        <div class="filo-cm-kpi"><div class="filo-cm-kpi-v">${summary.intl}</div><div class="filo-cm-kpi-l">${t(`cm_kpi_intl`)}</div></div>
                        <div class="filo-cm-kpi"><div class="filo-cm-kpi-v">${this._fmtRunway(summary.runway)}</div><div class="filo-cm-kpi-l">${t(`cm_kpi_runway`)}</div></div>
                    </div>
                    <div class="filo-cm-insights">
                        <div class="filo-cm-insights-title">${t(`cm_insights_title`)}</div>
                        <ul>${lis}</ul>
                    </div>
                </div>
            `;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const scale = Math.round(ds.scale);
            const brand = Math.round(ds.brand);
            const intl = Math.round(ds.intl);
            const runway = ds.runway;

            // Composite weights the pivot's pillars; a runway/tranche bonus on top.
            // v1.1.0: composite via _composite(ds) — single source of truth, value byte-identical to v1.0.0.
            const composite = this._composite(ds);

            const scalable = scale >= 55;
            const defensible = brand >= 50 && !ds.brandDiluted;
            const intlReady = intl >= 45;
            const founderFree = !ds.founderLocked;
            const wastedBudget = ds.budgetWasted;

            // v1.1.0: tier is now i18n-keyed (was hardcoded English) so it localizes.
            let performanceKey = `grade_stalled`;
            if (ds.trancheUnlocked && scalable && defensible && intlReady && composite >= 75) performanceKey = `grade_scalable`;
            else if (ds.trancheUnlocked) performanceKey = `grade_tranche`;
            else if (ds.brandDiluted) performanceKey = `grade_diluted`;
            else if (ds.founderLocked) performanceKey = `grade_founder`;
            else if (wastedBudget) performanceKey = `grade_burned`;
            else if (composite >= 55) performanceKey = `grade_mixed`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (ds.trancheUnlocked && scalable && defensible) insights.push(window.mySimulation.t(`insight_scalable`));
            else if (ds.brandDiluted) insights.push(window.mySimulation.t(`insight_diluted`));
            else if (!ds.trancheUnlocked) insights.push(window.mySimulation.t(`insight_stalled`));

            if (ds.founderLocked) insights.push(window.mySimulation.t(`insight_founder`));
            if (wastedBudget) insights.push(window.mySimulation.t(`insight_wasted`));
            if (!intlReady) insights.push(window.mySimulation.t(`insight_intl`));
            if (scalable && defensible && intlReady) insights.push(window.mySimulation.t(`insight_balanced`));

            return {
                totalPeriods: history.length,
                scale: scale,
                brand: brand,
                intl: intl,
                runway: runway,
                scalable: scalable,
                defensible: defensible,
                intlReady: intlReady,
                founderFree: founderFree,
                trancheUnlocked: ds.trancheUnlocked,
                composite: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.brandDiluted) return window.mySimulation.t(`hint_diluted`);
            if (ds.founderLocked) return window.mySimulation.t(`hint_founder`);
            if (ds.budgetWasted) return window.mySimulation.t(`hint_wasted`);
            if (state.currentPeriod >= 3 && ds.intl < 35) return window.mySimulation.t(`hint_intl`);
            if (state.currentPeriod >= 2 && ds.scale < 35) return window.mySimulation.t(`hint_scale`);
            if (ds.scale >= 60 && ds.brand >= 55 && ds.intl >= 45) return window.mySimulation.t(`hint_strong`);
            return null;
        }

